CREATE TABLE families(id SERIAL PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE users(id SERIAL PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,super_admin BOOLEAN NOT NULL DEFAULT false,active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE memberships(user_id INTEGER REFERENCES users(id),family_id INTEGER REFERENCES families(id),role TEXT NOT NULL CHECK(role IN ('family_admin','member')),PRIMARY KEY(user_id,family_id));
CREATE TABLE invitations(id UUID PRIMARY KEY,family_id INTEGER NOT NULL REFERENCES families(id),email TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('family_admin','member')),token_hash TEXT UNIQUE NOT NULL,expires_at TIMESTAMPTZ NOT NULL,used_at TIMESTAMPTZ,created_by INTEGER REFERENCES users(id));
CREATE TABLE otp_codes(id SERIAL PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),challenge UUID UNIQUE NOT NULL,code_hash TEXT NOT NULL,expires_at TIMESTAMPTZ NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,used_at TIMESTAMPTZ);
CREATE TABLE categories(id SERIAL PRIMARY KEY,name TEXT NOT NULL,slug TEXT UNIQUE NOT NULL,description TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE albums(id SERIAL PRIMARY KEY,family_id INTEGER NOT NULL REFERENCES families(id),title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE album_permissions(album_id INTEGER REFERENCES albums(id) ON DELETE CASCADE,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(album_id,user_id));
CREATE TABLE media(id SERIAL PRIMARY KEY,album_id INTEGER NOT NULL REFERENCES albums(id) ON DELETE CASCADE,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',type TEXT NOT NULL CHECK(type IN ('image','video')),storage_key UUID UNIQUE NOT NULL,mime TEXT NOT NULL,original_name TEXT NOT NULL,category_id INTEGER REFERENCES categories(id) ON DELETE SET NULL,views INTEGER NOT NULL DEFAULT 0,downloads INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE TABLE memories(id SERIAL PRIMARY KEY,album_id INTEGER NOT NULL REFERENCES albums(id),title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',occurred_on DATE NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE memory_media(memory_id INTEGER REFERENCES memories(id) ON DELETE CASCADE,media_id INTEGER REFERENCES media(id) ON DELETE CASCADE,PRIMARY KEY(memory_id,media_id));
CREATE TABLE comments(id SERIAL PRIMARY KEY,media_id INTEGER NOT NULL REFERENCES media(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id),content TEXT NOT NULL CHECK(length(content) BETWEEN 1 AND 500),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE reactions(media_id INTEGER REFERENCES media(id) ON DELETE CASCADE,user_id INTEGER REFERENCES users(id),emoji TEXT NOT NULL CHECK(emoji IN ('❤️','😍','🔥','👏')),PRIMARY KEY(media_id,user_id));
CREATE TABLE audit_logs(id BIGSERIAL PRIMARY KEY,actor_id INTEGER REFERENCES users(id),family_id INTEGER REFERENCES families(id),action TEXT NOT NULL,target TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE sessions(sid TEXT PRIMARY KEY,sess JSONB NOT NULL,expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE rate_limits(key TEXT PRIMARY KEY,hits INTEGER NOT NULL,expires_at TIMESTAMPTZ NOT NULL);
CREATE INDEX media_album_idx ON media(album_id) WHERE deleted_at IS NULL;
CREATE INDEX memories_date_idx ON memories(occurred_on);
CREATE INDEX sessions_expiry_idx ON sessions(expires_at);
